        case WM_RBUTTONUP:{auto menu=CreatePopupMenu();AppendMenuW(menu,MF_STRING,1,a->roam_?L"停在这里":L"继续走走");AppendMenuW(menu,MF_STRING,2,L"暂时隐藏");POINT p;GetCursorPos(&p);const auto command=TrackPopupMenu(menu,TPM_RETURNCMD|TPM_NONOTIFY,p.x,p.y,0,hwnd,nullptr);DestroyMenu(menu);if(command==1){a->roam_=!a->roam_;if(!a->roam_){a->targetX_=a->x_;a->targetY_=a->y_;a->state_="idle";a->stateUntil_=a->clock_+5;}}if(command==2){a->visible_=false;ShowWindow(hwnd,SW_HIDE);}return 0;}
